package sdkgen

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

const pyHeader = `# SPDX-License-Identifier: AGPL-3.0-only
# Code generated by internal/sdkgen from api/openapi.yaml. DO NOT EDIT.
# Regenerate with: make sdk
`

var pyKeywords = map[string]bool{
	"False": true, "None": true, "True": true, "and": true, "as": true, "assert": true,
	"async": true, "await": true, "break": true, "class": true, "continue": true, "def": true,
	"del": true, "elif": true, "else": true, "except": true, "finally": true, "for": true,
	"from": true, "global": true, "if": true, "import": true, "in": true, "is": true,
	"lambda": true, "nonlocal": true, "not": true, "or": true, "pass": true, "raise": true,
	"return": true, "try": true, "while": true, "with": true, "yield": true,
}

func pyIdent(name string) (string, error) {
	if pyKeywords[name] {
		return "", fmt.Errorf("%q is a Python keyword", name)
	}
	for i, r := range name {
		valid := r == '_' || r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || i > 0 && r >= '0' && r <= '9'
		if !valid {
			return "", fmt.Errorf("%q is not a Python identifier", name)
		}
	}
	return name, nil
}

// pyTypeExpr writes a Type as a Python annotation.
func pyTypeExpr(t *Type) string {
	var s string
	switch t.Kind {
	case KindString:
		s = "str"
	case KindInteger:
		s = "int"
	case KindNumber:
		s = "float"
	case KindBoolean:
		s = "bool"
	case KindArray:
		s = "List[" + pyTypeExpr(t.Items) + "]"
	case KindMap:
		s = "Dict[str, " + pyTypeExpr(t.Items) + "]"
	case KindRef:
		s = t.Ref
	case KindEnum:
		quoted := make([]string, len(t.Enum))
		for i, v := range t.Enum {
			quoted[i] = strconv.Quote(v)
		}
		s = "Literal[" + strings.Join(quoted, ", ") + "]"
	case KindLiteral:
		s = "Literal[" + strconv.Quote(t.Literal) + "]"
	case KindUnion:
		parts := make([]string, len(t.Variants))
		for i, v := range t.Variants {
			parts[i] = pyTypeExpr(v)
		}
		s = "Union[" + strings.Join(parts, ", ") + "]"
	default:
		return "Any"
	}
	if t.Nullable {
		s = "Optional[" + s + "]"
	}
	return s
}

// pyDocstring writes a docstring at the given indentation.
func pyDocstring(b *strings.Builder, indent, text string) {
	text = strings.TrimSpace(strings.ReplaceAll(strings.ReplaceAll(text, `\`, `\\`), `"""`, `\"\"\"`))
	if text == "" {
		return
	}
	lines := strings.Split(text, "\n")
	if len(lines) == 1 {
		fmt.Fprintf(b, "%s\"\"\"%s\"\"\"\n", indent, lines[0])
		return
	}
	fmt.Fprintf(b, "%s\"\"\"%s\n", indent, lines[0])
	for _, l := range lines[1:] {
		l = strings.TrimRight(l, " ")
		if l == "" {
			b.WriteString("\n")
		} else {
			fmt.Fprintf(b, "%s%s\n", indent, l)
		}
	}
	fmt.Fprintf(b, "%s\"\"\"\n", indent)
}

func pyComment(b *strings.Builder, indent, text string) {
	for _, l := range strings.Split(strings.TrimSpace(text), "\n") {
		if l = strings.TrimRight(l, " "); l == "" {
			fmt.Fprintf(b, "%s#\n", indent)
		} else {
			fmt.Fprintf(b, "%s# %s\n", indent, l)
		}
	}
}

// PythonModels writes models.py.
func PythonModels(api *API) ([]byte, error) {
	var b strings.Builder
	b.WriteString(pyHeader)
	fmt.Fprintf(&b, "\"\"\"The types of the %s %s, as TypedDicts.\n\n", api.Title, api.Version)
	b.WriteString("One per schema of components/schemas, and one per object a schema or an operation\n")
	b.WriteString("writes in place. They describe the JSON the client returns and takes; nothing is\n")
	b.WriteString("checked at run time.\n\"\"\"\n\n")
	b.WriteString("from __future__ import annotations\n\n")
	b.WriteString("from typing import Any, Dict, List, Literal, Optional, TypedDict, Union\n")

	var all []string
	// Aliases first: they are evaluated when the module loads, the classes'
	// annotations are not.
	for _, n := range api.Types {
		if n.Alias == nil {
			continue
		}
		b.WriteString("\n")
		if n.Doc != "" {
			pyComment(&b, "", n.Doc)
		}
		fmt.Fprintf(&b, "%s = %s\n", n.Name, pyTypeExpr(n.Alias))
		all = append(all, n.Name)
	}
	for _, n := range api.Types {
		if n.Alias != nil {
			continue
		}
		var req, opt []*Field
		keyword := false
		for _, f := range n.Fields {
			if pyKeywords[f.Name] {
				// A key such as "from" is fine in a dict but not in a class body.
				keyword = true
			} else if _, err := pyIdent(f.Name); err != nil {
				return nil, fmt.Errorf("%s.%s: %w", n.Name, f.Name, err)
			}
			if f.Required {
				req = append(req, f)
			} else {
				opt = append(opt, f)
			}
		}
		fields := func(fs []*Field) {
			for _, f := range fs {
				if f.Doc != "" {
					pyComment(&b, "    ", f.Doc)
				}
				fmt.Fprintf(&b, "    %s: %s\n", f.Name, pyTypeExpr(f.Type))
			}
		}
		// functional writes the TypedDict call syntax, which takes any key.
		functional := func(name string, fs []*Field, total bool) {
			fmt.Fprintf(&b, "%s = TypedDict(\n    %q,\n    {\n", name, name)
			for _, f := range fs {
				if f.Doc != "" {
					pyComment(&b, "        ", f.Doc)
				}
				fmt.Fprintf(&b, "        %q: %s,\n", f.Name, pyTypeExpr(f.Type))
			}
			b.WriteString("    },\n")
			if !total {
				b.WriteString("    total=False,\n")
			}
			b.WriteString(")\n")
		}
		b.WriteString("\n\n")
		switch {
		case keyword:
			var bases []string
			if len(req) > 0 {
				functional("_"+n.Name+"Required", req, true)
				bases = append(bases, "_"+n.Name+"Required")
			}
			if len(opt) > 0 {
				if len(req) > 0 {
					b.WriteString("\n\n")
				}
				functional("_"+n.Name+"Optional", opt, false)
				bases = append(bases, "_"+n.Name+"Optional")
			}
			fmt.Fprintf(&b, "\n\nclass %s(%s):\n", n.Name, strings.Join(bases, ", "))
			if n.Doc != "" {
				pyDocstring(&b, "    ", n.Doc)
			} else {
				b.WriteString("    pass\n")
			}
		case len(opt) == 0:
			fmt.Fprintf(&b, "class %s(TypedDict):\n", n.Name)
			pyDocstring(&b, "    ", n.Doc)
			if n.Doc != "" {
				b.WriteString("\n")
			}
			fields(req)
		case len(req) == 0:
			fmt.Fprintf(&b, "class %s(TypedDict, total=False):\n", n.Name)
			pyDocstring(&b, "    ", n.Doc)
			if n.Doc != "" {
				b.WriteString("\n")
			}
			fields(opt)
		default:
			// Python 3.9 has no NotRequired: the required keys go in a base class.
			fmt.Fprintf(&b, "class _%sRequired(TypedDict):\n", n.Name)
			fields(req)
			fmt.Fprintf(&b, "\n\nclass %s(_%sRequired, total=False):\n", n.Name, n.Name)
			pyDocstring(&b, "    ", n.Doc)
			if n.Doc != "" {
				b.WriteString("\n")
			}
			fields(opt)
		}
		all = append(all, n.Name)
	}
	sort.Strings(all)
	b.WriteString("\n\n__all__ = [\n")
	for _, n := range all {
		fmt.Fprintf(&b, "    %q,\n", n)
	}
	b.WriteString("]\n")
	return []byte(b.String()), nil
}

func pyResult(op *Operation) string {
	switch op.Result {
	case ResultJSON:
		return pyTypeExpr(op.ResultType)
	case ResultBinary:
		return "bytes"
	}
	return "None"
}

func pyPath(op *Operation) string {
	p := op.Path
	for _, pp := range op.PathParams {
		p = strings.ReplaceAll(p, "{"+pp.Name+"}", "{_path("+pp.Ident+")}")
	}
	if strings.Contains(p, "{_path(") {
		return "f" + strconv.Quote(p)
	}
	return strconv.Quote(p)
}

// pyArgs is the parameter list of a method, after self.
func pyArgs(op *Operation, iter bool) []string {
	var args []string
	for _, p := range op.PathParams {
		args = append(args, p.Ident+": "+pyTypeExpr(p.Type))
	}
	if op.Body != nil {
		t := "bytes"
		if !op.Body.Binary {
			t = pyTypeExpr(op.Body.Type)
		}
		if op.Body.Required {
			args = append(args, "body: "+t)
		} else {
			args = append(args, "body: Optional["+t+"] = None")
		}
	}
	var kw []string
	for _, p := range tsParams(op) {
		if iter && p.Name == "cursor" {
			continue
		}
		if p.Required {
			kw = append(kw, p.Ident+": "+pyTypeExpr(p.Type))
		} else {
			t := pyTypeExpr(p.Type)
			if !p.Type.Nullable {
				t = "Optional[" + t + "]"
			}
			kw = append(kw, p.Ident+": "+t+" = None")
		}
	}
	if op.Idempotent {
		kw = append(kw, "idempotency_key: Optional[str] = None")
	}
	if len(kw) > 0 {
		args = append(args, "*")
		args = append(args, kw...)
	}
	return args
}

func pySignature(b *strings.Builder, name string, args []string, ret string) {
	if len(args) == 0 {
		fmt.Fprintf(b, "    def %s(self) -> %s:\n", name, ret)
		return
	}
	one := fmt.Sprintf("    def %s(self, %s) -> %s:\n", name, strings.Join(args, ", "), ret)
	if len(one) <= 100 {
		b.WriteString(one)
		return
	}
	fmt.Fprintf(b, "    def %s(\n        self,\n", name)
	for _, a := range args {
		fmt.Fprintf(b, "        %s,\n", a)
	}
	fmt.Fprintf(b, "    ) -> %s:\n", ret)
}

func pyOpDoc(op *Operation) string {
	var parts []string
	if op.Summary != "" {
		parts = append(parts, strings.TrimSuffix(op.Summary, ".")+".")
	}
	parts = append(parts, fmt.Sprintf("``%s %s``", strings.ToUpper(op.Method), op.Path))
	if op.Description != "" {
		parts = append(parts, op.Description)
	}
	if op.Auth == "user" {
		parts = append(parts, "Needs a user token (ohs_ut_) as the client's api_key.")
	}
	var args []string
	for _, p := range tsParams(op) {
		if p.Doc == "" {
			continue
		}
		doc := strings.ReplaceAll(strings.TrimSpace(p.Doc), "\n", "\n        ")
		if p.In == "header" {
			doc = "Sent as the " + p.Name + " header. " + doc
		}
		args = append(args, fmt.Sprintf("    %s: %s", p.Ident, doc))
	}
	if len(args) > 0 {
		parts = append(parts, "Args:\n"+strings.Join(args, "\n"))
	}
	return strings.Join(parts, "\n\n")
}

// pyCall writes a call spread over lines: name(\n    arg,\n).
func pyCall(b *strings.Builder, indent, prefix string, args []string, suffix string) {
	fmt.Fprintf(b, "%s%s(\n", indent, prefix)
	for _, a := range args {
		fmt.Fprintf(b, "%s    %s,\n", indent, a)
	}
	fmt.Fprintf(b, "%s)%s\n", indent, suffix)
}

func pyDict(indent string, items [][2]string) string {
	var b strings.Builder
	b.WriteString("{\n")
	for _, kv := range items {
		fmt.Fprintf(&b, "%s    %q: %s,\n", indent, kv[0], kv[1])
	}
	b.WriteString(indent + "}")
	return b.String()
}

func pyMethod(b *strings.Builder, op *Operation) {
	name := snake(op.ID)
	pySignature(b, name, pyArgs(op, false), pyResult(op))
	pyDocstring(b, "        ", pyOpDoc(op))
	args := []string{strconv.Quote(strings.ToUpper(op.Method)), pyPath(op)}
	if len(op.QueryParams) > 0 {
		var items [][2]string
		for _, p := range op.QueryParams {
			items = append(items, [2]string{p.Name, p.Ident})
		}
		args = append(args, "query="+pyDict("            ", items))
	}
	if len(op.Headers) > 0 {
		var items [][2]string
		for _, p := range op.Headers {
			items = append(items, [2]string{p.Name, p.Ident})
		}
		args = append(args, "headers="+pyDict("            ", items))
	}
	if op.Body != nil {
		if op.Body.Binary {
			args = append(args, "data=body", fmt.Sprintf("content_type=%q", op.Body.ContentType))
		} else {
			args = append(args, "json_body=body")
		}
	}
	if op.Idempotent {
		args = append(args, "idempotency_key=idempotency_key")
	}
	expect := map[string]string{ResultJSON: "json", ResultNone: "none", ResultBinary: "bytes"}[op.Result]
	if expect != "json" {
		args = append(args, fmt.Sprintf("expect=%q", expect))
	}
	pyCall(b, "        ", "return self._request", args, "")
}

func pyIterator(b *strings.Builder, op *Operation) {
	name := snake(IterName(op.ID))
	pySignature(b, name, pyArgs(op, true), "Iterator["+pyTypeExpr(op.ItemType)+"]")
	pyDocstring(b, "        ", fmt.Sprintf("Every item of :meth:`%s`, page after page, following ``next_cursor``.", snake(op.ID)))
	var call []string
	for _, p := range op.PathParams {
		call = append(call, p.Ident)
	}
	for _, p := range tsParams(op) {
		call = append(call, p.Ident+"="+p.Ident)
	}
	b.WriteString("        return paginate(\n")
	pyCall(b, "            ", "lambda cursor: self."+snake(op.ID), call, "")
	b.WriteString("        )\n")
}

// PythonClient writes client.py.
func PythonClient(api *API) ([]byte, error) {
	var b strings.Builder
	b.WriteString(pyHeader)
	fmt.Fprintf(&b, "\"\"\"A client of the %s %s, on the Python standard library alone.\n\n", api.Title, api.Version)
	b.WriteString("One method per operation of the document. Python 3.9 or later.\n\"\"\"\n\n")
	b.WriteString(pyImports)

	used := map[string]bool{}
	for _, op := range api.Ops {
		collectRefs(op.ResultType, used)
		collectRefs(op.ItemType, used)
		if op.Body != nil {
			collectRefs(op.Body.Type, used)
		}
		for _, p := range append(append(append([]*Param{}, op.PathParams...), op.QueryParams...), op.Headers...) {
			if _, err := pyIdent(p.Ident); err != nil {
				return nil, fmt.Errorf("%s: %w", op.ID, err)
			}
			collectRefs(p.Type, used)
		}
	}
	names := make([]string, 0, len(used))
	for n := range used {
		names = append(names, n)
	}
	sort.Strings(names)
	b.WriteString("from .models import (\n")
	for _, n := range names {
		fmt.Fprintf(&b, "    %s,\n", n)
	}
	b.WriteString(")\n")
	b.WriteString(pyRuntime)
	for _, op := range api.Ops {
		b.WriteString("\n")
		pyMethod(&b, op)
		if op.Paged {
			b.WriteString("\n")
			pyIterator(&b, op)
		}
	}
	return []byte(b.String()), nil
}

const pyImports = `from __future__ import annotations

import json
import urllib.error
import urllib.parse
import urllib.request
from typing import Any, Callable, Dict, Iterator, Literal, Mapping, Optional, TypeVar, Union

`

const pyRuntime = `
__all__ = ["OhsError", "OpenHealthSync", "paginate"]

T = TypeVar("T")


class OhsError(Exception):
    """An error answer of the API, read from its application/problem+json body."""

    def __init__(
        self,
        status: int,
        title: str,
        *,
        detail: Optional[str] = None,
        type: Optional[str] = None,
        request_id: Optional[str] = None,
        body: Any = None,
    ) -> None:
        super().__init__(f"{status} {title}: {detail}" if detail else f"{status} {title}")
        #: The HTTP status code.
        self.status = status
        #: The problem's title, or the reason phrase when the body is not a problem.
        self.title = title
        #: The problem's detail, when it has one.
        self.detail = detail
        #: The problem's type URI.
        self.type = type
        #: The X-Request-Id of the response, to quote when reporting the error.
        self.request_id = request_id
        #: The parsed body (a Problem), or its text when it is not JSON.
        self.body = body

    @classmethod
    def from_http_error(cls, err: urllib.error.HTTPError) -> OhsError:
        """Reads an error response."""
        text = err.read().decode("utf-8", errors="replace")
        body: Any = text
        try:
            body = json.loads(text)
        except ValueError:
            pass
        problem = body if isinstance(body, dict) else {}
        return cls(
            err.code,
            problem.get("title") or str(err.reason),
            detail=problem.get("detail"),
            type=problem.get("type"),
            request_id=err.headers.get("X-Request-Id") or problem.get("request_id"),
            body=body,
        )


def paginate(fetch_page: Callable[[Optional[str]], Mapping[str, Any]]) -> Iterator[Any]:
    """Yields every item of a list, fetching page after page until next_cursor is null."""
    cursor: Optional[str] = None
    while True:
        page = fetch_page(cursor)
        yield from page["data"]
        cursor = page.get("next_cursor")
        if not cursor:
            return


def _path(value: Union[str, int]) -> str:
    return urllib.parse.quote(str(value), safe="")


def _text(value: Any) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


class OpenHealthSync:
    """A client of the Open Health Sync API.

    ::

        ohs = OpenHealthSync("https://health.example.com", os.environ["OHS_API_KEY"])
        user = ohs.create_user({"external_ref": "customer-42"})

    api_key is a tenant API key (ohs_sk_...), or a user token (ohs_ut_...) for the user
    routes. timeout is in seconds, per request.
    """

    def __init__(self, base_url: str, api_key: str, *, timeout: float = 30.0) -> None:
        if not base_url:
            raise ValueError("base_url is required")
        if not api_key:
            raise ValueError("api_key is required")
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self._api_key = api_key

    def _request(
        self,
        method: str,
        path: str,
        *,
        query: Optional[Dict[str, Any]] = None,
        headers: Optional[Dict[str, Any]] = None,
        json_body: Any = None,
        data: Optional[bytes] = None,
        content_type: Optional[str] = None,
        idempotency_key: Optional[str] = None,
        expect: Literal["json", "none", "bytes"] = "json",
    ) -> Any:
        url = self.base_url + path
        params = {k: _text(v) for k, v in (query or {}).items() if v is not None}
        if params:
            url += "?" + urllib.parse.urlencode(params)
        sent = {"Authorization": f"Bearer {self._api_key}"}
        if expect == "json":
            sent["Accept"] = "application/json"
        for name, value in (headers or {}).items():
            if value is not None:
                sent[name] = _text(value)
        body = data
        if json_body is not None:
            body = json.dumps(json_body).encode("utf-8")
            sent["Content-Type"] = "application/json"
        elif data is not None:
            sent["Content-Type"] = content_type or "application/octet-stream"
        if idempotency_key:
            sent["Idempotency-Key"] = idempotency_key

        request = urllib.request.Request(url, data=body, headers=sent, method=method)
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                raw = response.read()
        except urllib.error.HTTPError as err:
            raise OhsError.from_http_error(err) from None
        if expect == "none":
            return None
        if expect == "bytes":
            return raw
        return json.loads(raw)
`
